<script lang="ts">
  import DiffViewSwitcher from '../diffs/DiffViewSwitcher.svelte'
  import type { DiffView } from '../diffs/types'
  import { parseHunkPatch, projectHunkCodeVersion } from './types'
  import type { HunkReviewComment, HunkReviewDiscussion, HunkReviewFile, HunkReviewMode, HunkReviewSnapshot } from './types'

  let { hunk, emptyMessage = 'No captured diff is available for this Hunk.', showComments = true, focusComment, diffView, parentBranch = null, parentAvailable = false, masterBranch = null, masterAvailable = true, masterIsCurrent = false, diffViewBusy = false, onDiffViewChange }: { hunk: HunkReviewSnapshot; emptyMessage?: string; showComments?: boolean; focusComment?: HunkReviewComment | null; diffView?: DiffView; parentBranch?: string | null; parentAvailable?: boolean; masterBranch?: string | null; masterAvailable?: boolean; masterIsCurrent?: boolean; diffViewBusy?: boolean; onDiffViewChange?: (view: DiffView) => void } = $props()
  const MIN_FILES_WIDTH = 180
  const MAX_FILES_WIDTH = 560
  let filesWidth = $state(260)
  let resizingFiles = $state(false)
  let selectedIndex = $state(0)
  let mode = $state<HunkReviewMode>('diff')
  let selectedFile = $derived(hunk.files[selectedIndex] ?? null)
  let blocks = $derived(joinNearbyBlocks(selectedFile ? parseHunkPatch(selectedFile.patch) : []))
  let codeBlocks = $derived(mode === 'diff' ? [] : projectHunkCodeVersion(blocks, mode))
  let usableThreads = $derived((hunk.discussions ?? []).map(withHumanNotes).filter((thread) => thread.notes.length > 0))
  let positionedThreads = $derived(usableThreads.filter((thread) => thread.notes.some((note) => belongsToFile(note, selectedFile) && lineFor(note) != null)))
  let generalThreads = $derived(usableThreads.filter((thread) => thread.notes.some((note) => lineFor(note) == null)))
  let commentLinks = $derived(usableThreads.flatMap((thread) => thread.notes.filter((note) => note.position && lineFor(note) != null).map((note) => ({ thread, note }))))

  function withHumanNotes(thread: HunkReviewDiscussion): HunkReviewDiscussion & { notes: HunkReviewComment[] } { return { ...thread, notes: (thread.notes ?? []).filter((note) => !note.system) } }
  function startFilesResize(event: MouseEvent) { event.preventDefault(); resizingFiles = true; document.body.style.cursor = 'col-resize'; document.body.style.userSelect = 'none' }
  $effect(() => {
    const move = (event: MouseEvent) => { if (!resizingFiles) return; const root = document.querySelector('.hunk-review') as HTMLElement | null; if (!root) return; filesWidth = Math.max(MIN_FILES_WIDTH, Math.min(MAX_FILES_WIDTH, event.clientX - root.getBoundingClientRect().left)) }
    const stop = () => { if (!resizingFiles) return; resizingFiles = false; document.body.style.cursor = ''; document.body.style.userSelect = '' }
    window.addEventListener('mousemove', move); window.addEventListener('mouseup', stop); return () => { window.removeEventListener('mousemove', move); window.removeEventListener('mouseup', stop) }
  })
  function joinNearbyBlocks(input: ReturnType<typeof parseHunkPatch>) {
    return input.reduce<typeof input>((joined, block) => {
      const previous = joined.at(-1)
      // A visual split within forty source lines is noisier than useful. The captured
      // patch still determines which exact lines are rendered; this removes the extra header.
      if (previous && block.oldStart - (previous.oldStart + previous.oldCount) <= 40 && block.newStart - (previous.newStart + previous.newCount) <= 40) previous.lines.push(...block.lines)
      else joined.push({ ...block, lines: [...block.lines] })
      return joined
    }, [])
  }
  function pathFor(file: HunkReviewFile | null) { return file?.path ?? '' }
  function belongsToFile(note: HunkReviewComment, file: HunkReviewFile | null) { return !!file && !!note.position && (note.position.new_path === file.path || note.position.old_path === file.path || note.position.new_path === file.old_path || note.position.old_path === file.old_path) }
  function lineFor(note: HunkReviewComment): number | null { return note.position?.new_line ?? note.position?.old_line ?? null }
  function lineId(file: HunkReviewFile | null, line: number) { return `hunk-line-${encodeURIComponent(pathFor(file))}-${line}` }
  function threadsForLine(oldLine: number | undefined, newLine: number | undefined) { return positionedThreads.filter((thread) => thread.notes.some((note) => belongsToFile(note, selectedFile) && ((note.position?.new_line != null && note.position.new_line === newLine) || (note.position?.old_line != null && note.position.old_line === oldLine)))) }
  $effect(() => { if (focusComment?.position) goToComment(focusComment) })
  function goToComment(note: HunkReviewComment) {
    const path = note.position?.new_path || note.position?.old_path; const line = lineFor(note)
    const index = hunk.files.findIndex((file) => file.path === path || file.old_path === path)
    if (index >= 0) selectedIndex = index
    if (line != null) setTimeout(() => document.getElementById(lineId(hunk.files[index >= 0 ? index : selectedIndex], line))?.scrollIntoView({ behavior: 'smooth', block: 'center' }), 0)
  }
  const sign = (kind: string) => kind === 'addition' ? '+' : kind === 'deletion' ? '−' : kind === 'no-newline' ? '\\' : ' '
</script>

<div class="hunk-review" style={`grid-template-columns:${filesWidth}px 6px minmax(0,1fr)`}>
  {#if !hunk.files.length}<p class="empty">{emptyMessage}</p>
  {:else}<aside aria-label="Changed files"><h2>Files</h2><div class="file-list" aria-label="Changed files list"><div class="file-list-content">{#each hunk.files as file, index}<button class:active={selectedIndex === index} onclick={() => selectedIndex = index}>{pathFor(file)}</button>{/each}</div></div></aside><div class="files-resizer" role="separator" aria-orientation="vertical" aria-label="Resize files column" title="Drag to resize files column · double-click to reset" onmousedown={startFilesResize} ondblclick={() => filesWidth = 260}></div>
  <main>
    {#if showComments && usableThreads.length}<details class="comments"><summary>Comments ({usableThreads.reduce((count, thread) => count + thread.notes.length, 0)})</summary>
      {#if generalThreads.length}<section><h3>General comments</h3>{#each generalThreads as thread (thread.id ?? `general-${generalThreads.indexOf(thread)}`)}{@render Thread(thread)}{/each}</section>{/if}
      {#if commentLinks.length}<section><h3>Comments on code</h3>{#each commentLinks as { thread, note } (`${thread.id ?? 'thread'}-${note.id ?? note.created_at}`)}<button class="comment-link" onclick={() => goToComment(note)}><strong>{note.author?.name || 'Unknown author'}</strong><span>{note.position?.new_path || note.position?.old_path}:{lineFor(note)}</span><p>{note.body || ''}</p></button>{/each}</section>{/if}
    </details>{/if}
    <header class="review-toolbar"><div class="file-title">{pathFor(selectedFile)}</div>{#if diffView && onDiffViewChange}<DiffViewSwitcher view={diffView} {parentBranch} {parentAvailable} {masterBranch} {masterAvailable} {masterIsCurrent} busy={diffViewBusy} onChange={onDiffViewChange} />{/if}<div class="modes" role="group" aria-label="Review mode">{#each [['before', 'Before'], ['diff', 'Diff'], ['after', 'After']] as [value, label]}<button class:active={mode === value} onclick={() => mode = value as HunkReviewMode}>{label}</button>{/each}</div></header>
    <div class="patch" aria-label={mode === 'diff' ? 'Captured unified diff' : mode === 'before' ? 'Code before changes' : 'Code after changes'}>
      {#if !blocks.length}<p class="empty">No textual differences to display.</p>
      {:else if mode === 'diff'}{#each blocks as block}<div class="block-header">@@ −{block.oldStart},{block.oldCount} +{block.newStart},{block.newCount} @@</div>{#each block.lines as line}<div id={lineFor({ position: { old_line: line.oldLine, new_line: line.newLine } }) ? lineId(selectedFile, line.newLine ?? line.oldLine!) : undefined} class="line diff-line {line.kind}"><span class="old">{line.oldLine ?? ''}</span><span class="new">{line.newLine ?? ''}</span><span class="sign">{sign(line.kind)}</span><code>{line.text || ' '}</code></div>{#each threadsForLine(line.oldLine, line.newLine) as thread (thread.id ?? `${line.oldLine}-${line.newLine}`)}<div class="thread-row">{@render Thread(thread)}</div>{/each}{/each}{/each}
      {:else}{#each codeBlocks as block}<div class="block-header">{mode === 'before' ? `Before changes · line ${block.start}` : `After changes · line ${block.start}`}</div>{#each block.rows as row}{#if row.kind === 'cue'}<div class="cue {row.tone}"><span></span><strong>{row.tone === 'added' ? '+' : '−'}{row.count} {row.count === 1 ? 'line' : 'lines'} {row.tone === 'added' ? 'inserted here' : 'removed here'}</strong><span></span></div>{:else}<div id={lineId(selectedFile, row.lineNumber)} class="line code-line {row.tone}"><span class="number">{row.lineNumber}</span><span class="change-bar"></span><code>{row.line.text || ' '}</code></div>{/if}{/each}{/each}{/if}
    </div>
  </main>{/if}
</div>
{#snippet Thread(thread: HunkReviewDiscussion)}<article class="thread">{#each thread.notes ?? [] as note (note.id ?? note.created_at ?? note.body)}<div class="note"><header><strong>{note.author?.name || 'Unknown author'}</strong><span>{note.resolved ? 'Resolved' : ''}{note.created_at ? `${note.resolved ? ' · ' : ''}${new Date(note.created_at).toLocaleString()}` : ''}</span></header><p>{note.body || ''}</p></div>{/each}</article>{/snippet}
<style>
.hunk-review{box-sizing:border-box;width:100%;max-width:100%;height:100%;min-width:0;min-height:0;overflow:hidden;display:grid;background:var(--arbol-color-bg);color:var(--arbol-color-text)}aside{min-width:0;border-right:0 solid var(--arbol-color-border);padding:10px;overflow:hidden;display:grid;grid-template-rows:auto minmax(0,1fr)}h2{font-size:13px;margin:5px 0 10px}.file-list{min-width:0;min-height:0;overflow:auto;scrollbar-gutter:stable both-edges;white-space:nowrap}.file-list-content{display:block;width:max-content;min-width:100%;padding-bottom:2px}aside button{display:block;width:max-content;min-width:100%;text-align:left;border:0;border-radius:4px;margin-bottom:2px;padding:7px;font:11px var(--arbol-font-mono);color:inherit;background:transparent;white-space:nowrap;cursor:pointer}aside button.active{background:var(--arbol-color-accent-soft);color:var(--arbol-color-accent)}.files-resizer{cursor:col-resize;background:var(--arbol-color-bg);position:relative}.files-resizer::after{content:'';position:absolute;inset:0 2px;background:var(--arbol-color-border)}main{width:100%;max-width:100%;min-width:0;min-height:0;overflow:hidden;display:grid;grid-template-rows:auto auto minmax(0,1fr)}.comments{box-sizing:border-box;min-width:0;max-height:min(36vh,320px);overflow:auto;padding:10px 12px;border-bottom:1px solid var(--arbol-color-border);font:12px var(--arbol-font-sans)}.comments summary{cursor:pointer;font-weight:650}.comments section{min-width:0;margin-top:12px}.comments h3{margin:0 0 7px;color:var(--arbol-color-text-muted);font:650 10px var(--arbol-font-ui);text-transform:uppercase}.review-toolbar{box-sizing:border-box;width:100%;min-width:0;display:flex;align-items:center;justify-content:space-between;gap:10px;overflow-x:auto;overflow-y:hidden;border-bottom:1px solid var(--arbol-color-border)}.file-title{min-width:100px;flex:1 1 auto;padding:9px 12px;font:600 12px var(--arbol-font-mono);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.modes{flex:none;display:flex;gap:2px;padding:5px}.modes button{border:0;border-radius:4px;padding:5px 8px;background:transparent;color:var(--arbol-color-text-muted);font:600 11px var(--arbol-font-ui);cursor:pointer}.modes button.active{background:var(--arbol-color-accent-soft);color:var(--arbol-color-accent)}.patch{box-sizing:border-box;width:100%;max-width:100%;min-width:0;min-height:0;overflow:auto;overscroll-behavior:contain;font:11px/1.55 var(--arbol-font-mono)}.block-header{position:sticky;top:0;z-index:1;padding:6px 12px;background:color-mix(in oklch,var(--arbol-color-accent-soft) 80%,var(--arbol-color-bg));color:var(--arbol-color-accent);border-block:1px solid var(--arbol-color-border)}.line{min-height:20px}.diff-line{display:grid;grid-template-columns:48px 48px 22px minmax(max-content,1fr)}.diff-line.addition{background:color-mix(in oklch,var(--arbol-color-ok) 12%,transparent)}.diff-line.deletion{background:color-mix(in oklch,var(--arbol-color-err) 12%,transparent)}.diff-line.no-newline{color:var(--arbol-color-text-muted);font-style:italic}.old,.new{padding:2px 8px;text-align:right;user-select:none;color:var(--arbol-color-text-muted);border-right:1px solid var(--arbol-color-border)}.sign{padding:2px 6px;user-select:none}code{padding:2px 12px 2px 0;white-space:pre}.code-line{display:grid;grid-template-columns:58px 4px minmax(max-content,1fr)}.code-line.removed{background:color-mix(in oklch,var(--arbol-color-err) 14%,transparent)}.code-line.added{background:color-mix(in oklch,var(--arbol-color-ok) 14%,transparent)}.code-line.edited{background:color-mix(in oklch,var(--arbol-color-link) 14%,transparent)}.code-line.removed .change-bar{background:var(--arbol-color-err)}.code-line.added .change-bar{background:var(--arbol-color-ok)}.code-line.edited .change-bar{background:var(--arbol-color-link)}.number{padding:2px 9px;text-align:right;user-select:none;color:var(--arbol-color-text-muted);border-right:1px solid var(--arbol-color-border)}.code-line code{padding-left:12px}.cue{display:grid;grid-template-columns:minmax(18px,1fr) auto minmax(18px,5fr);align-items:center;gap:8px;min-height:20px;padding-left:62px;user-select:none}.cue span{height:2px;border-radius:2px}.cue strong{font:650 9px/1 var(--arbol-font-ui);white-space:nowrap}.cue.added{color:var(--arbol-color-ok);background:color-mix(in oklch,var(--arbol-color-ok) 5%,transparent)}.cue.added span{background:var(--arbol-color-ok)}.cue.removed{color:var(--arbol-color-err);background:color-mix(in oklch,var(--arbol-color-err) 5%,transparent)}.cue.removed span{background:var(--arbol-color-err)}.thread-row{padding:5px 12px 8px 118px;border-bottom:1px solid var(--arbol-color-border)}.thread{border:1px solid var(--arbol-color-border);border-radius:7px;background:var(--arbol-color-surface);font:12px/1.4 var(--arbol-font-sans)}.note{padding:9px 11px}.note+.note{border-top:1px solid var(--arbol-color-border)}.note header{display:flex;justify-content:space-between;gap:8px;font-size:11px}.note header span{color:var(--arbol-color-text-muted)}.note p{overflow-wrap:anywhere;white-space:pre-wrap;margin:7px 0 0}.comment-link{display:block;box-sizing:border-box;min-width:0;width:100%;margin:5px 0;padding:7px 9px;border:1px solid var(--arbol-color-border);border-radius:5px;background:var(--arbol-color-surface);color:inherit;text-align:left;cursor:pointer;font:11px var(--arbol-font-sans)}.comment-link span{margin-left:8px;color:var(--arbol-color-link);font-family:var(--arbol-font-mono);overflow-wrap:anywhere}.comment-link p{overflow:hidden;margin:4px 0 0;color:var(--arbol-color-text-muted);text-overflow:ellipsis;white-space:nowrap}.empty{height:100%;margin:0;display:grid;place-items:center;padding:30px;color:var(--arbol-color-text-muted);text-align:center}@media(max-width:760px){.hunk-review{grid-template-columns:minmax(150px,36%) 0 minmax(0,1fr)!important}.files-resizer{display:none}.thread-row{padding-left:12px}.review-toolbar{align-items:start;flex-direction:column}.modes{padding-top:0}}
</style>
